import { createRoute, z } from '@hono/zod-openapi'

const AccountSchema = z
  .object({
    email: z.string().openapi({ description: "User's email address." }),
    first_name: z.string().openapi({ description: "User's first name." }),
    last_name: z.string().openapi({ description: "User's last name." }),
    options: z
      .object({
        billing_auto_renew: z
          .boolean()
          .exactOptional()
          .openapi({ description: 'Toggle whether automatic billing renewal is on or off.' }),
        meeting_connector_list: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'Specify the IP addresses of the Meeting Connectors that you would like to share with the sub account. Multiple values can be separated by comma. If no value is provided in this field, all the Meeting Connectors of a master account will be shared with the sub account.\n\n\n**Note:** This option can only be used if the value of `share_mc` is set to `true`.',
          }),
        pay_mode: z
          .enum(['master', 'sub'])
          .default('master')
          .exactOptional()
          .openapi({
            description:
              'Payee:<br>`master` - master account holder pays.<br>`sub` - Sub account holder pays.',
            'x-enum-descriptions': ['master account holder pays', 'Sub account holder pays'],
          }),
        room_connector_list: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'Specify the IP addresses of the Room Connectors that you would like to share with the sub account. Multiple values can be separated by comma. If no value is provided in this field, all the Room Connectors of a master account will be shared with the sub account.\n\n\n**Note:** This option can only be used if the value of `share_rc` is set to `true`.',
          }),
        share_mc: z
          .boolean()
          .default(false)
          .exactOptional()
          .openapi({
            description:
              'Enable/disable the option for a sub account to use shared [Meeting Connector(s)](https://support.zoom.us/hc/en-us/articles/201363093-Getting-Started-with-the-Meeting-Connector) that are set up by the master account. Meeting Connectors can only be used by On-prem users.',
          }),
        share_rc: z
          .boolean()
          .default(false)
          .exactOptional()
          .openapi({
            description:
              'Enable/disable the option for a sub account to use shared [Virtual Room Connector(s)](https://support.zoom.us/hc/en-us/articles/202134758-Getting-Started-With-Virtual-Room-Connector) that are set up by the master account. Virtual Room Connectors can only be used by On-prem users.',
          }),
      })
      .exactOptional()
      .openapi({ description: 'Account options object.', required: [] }),
    password: z.string().openapi({ description: "User's password." }),
    vanity_url: z.string().exactOptional().openapi({ description: 'Account Vanity URL' }),
  })
  .openapi({
    description:
      "The account object represents an account on Zoom. The account owner is the user who created the account or had an account created for them. You can read more about the Zoom account structure <a href='https://medium.com/zoom-developer-blog/a-brief-look-at-zoom-account-structures-1d19c745bf8a' target='_blank'>here</a>.",
    required: ['first_name', 'last_name', 'email', 'password'],
  })
  .openapi('Account')

const AccountListSchema = z
  .object({
    next_page_token: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The next page token is used to paginate through large result sets. A next page token will be returned whenever the set of available results exceeds the current page size. The expiration period for this token is 15 minutes.',
      }),
    page_count: z
      .int()
      .exactOptional()
      .openapi({ description: 'The number of pages returned for the request made.' }),
    page_number: z
      .int()
      .default(1)
      .exactOptional()
      .openapi({
        description:
          '**Deprecated**: This field has been deprecated. Please use the "next_page_token" field for pagination instead of this field.\n\nThe page number of the current results.',
      }),
    page_size: z
      .int()
      .max(300)
      .default(30)
      .exactOptional()
      .openapi({ description: 'The number of records returned with a single API call.' }),
    total_records: z
      .int()
      .exactOptional()
      .openapi({ description: 'The total number of all the records available across pages.' }),
  })
  .openapi({ description: 'Pagination Object.', required: [] })
  .and(
    z
      .object({
        accounts: z
          .array(
            z
              .object({
                account_name: z.string().exactOptional().openapi({ description: 'Account name.' }),
                account_number: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Account Number of the account.' }),
                account_type: z.string().exactOptional().openapi({ description: 'Account type.' }),
                created_at: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'Account creation date and time.' }),
                id: z.string().exactOptional().openapi({ description: 'Account ID.' }),
                owner_email: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Account owner email.', example: 'john.doe@zoom.us' }),
                seats: z.int().exactOptional().openapi({ description: 'Account seats.' }),
                subscription_end_time: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'Account subscription end date and time.' }),
                subscription_start_time: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'Account subscription start date and time.' }),
              })
              .openapi({ required: [] }),
          )
          .exactOptional()
          .openapi({ description: 'List of Account objects.' }),
      })
      .openapi({ description: 'Account object in the account list.', required: [] }),
  )
  .openapi({ description: 'List of Accounts.', title: 'Account List' })
  .openapi('AccountList')

