const UserSchema = z
  .object({
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'User create time.' }),
    dept: z.string().exactOptional().openapi({ description: 'Department.' }),
    email: z
      .string()
      .default('john.doe@email.com')
      .openapi({ description: "User's email address." }),
    first_name: z.string().max(64).exactOptional().openapi({ description: "User's first name." }),
    last_client_version: z
      .string()
      .exactOptional()
      .openapi({ description: 'User last login client version.' }),
    last_login_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'User last login time.' }),
    last_name: z.string().max(64).exactOptional().openapi({ description: "User's last name." }),
    pmi: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64', description: 'Personal meeting ID.' }),
    role_name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "User's [role](https://support.zoom.us/hc/en-us/articles/115001078646-Role-Based-Access-Control) name.",
      }),
    timezone: z.string().exactOptional().openapi({ description: 'The time zone of the user.' }),
    type: z
      .union([z.literal(1), z.literal(2), z.literal(3), z.literal(99)])
      .openapi({
        description:
          "User's plan type:<br>`1` - Basic.<br>`2` - Licensed.<br>`3` - On-prem.<br>`99` - None (this can only be set with `ssoCreate`).",
      }),
    use_pmi: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({ description: 'Use Personal Meeting ID for instant meetings.' }),
  })
  .openapi({
    description: 'The user object represents a specific user on Zoom.',
    required: ['email', 'type'],
  })
  .openapi('User')

