const ZoomRoomSchema = z
  .object({
    account_type: z.string().exactOptional().openapi({ description: 'Zoom room email type.' }),
    calender_name: z.string().exactOptional().openapi({ description: 'Zoom calendar name.' }),
    camera: z.string().exactOptional().openapi({ description: 'Zoom room camera.' }),
    device_ip: z.string().exactOptional().openapi({ description: 'Zoom room device IP.' }),
    email: z.string().exactOptional().openapi({ description: 'Zoom room email.' }),
    health: z.string().exactOptional(),
    id: z.string().exactOptional().openapi({ description: 'Zoom room ID.' }),
    issues: z.array(z.string()).exactOptional().openapi({ description: 'Zoom Room issues.' }),
    last_start_time: z
      .string()
      .exactOptional()
      .openapi({ description: 'Zoom room last start time.' }),
    location: z.string().exactOptional().openapi({ description: 'Zoom room location.' }),
    microphone: z.string().exactOptional().openapi({ description: 'Zoom room microphone.' }),
    room_name: z.string().exactOptional().openapi({ description: 'Zoom room name.' }),
    speaker: z.string().exactOptional().openapi({ description: 'Zoom room speaker.' }),
    status: z.string().exactOptional().openapi({ description: 'Zoom room status.' }),
  })
  .openapi({ description: 'Zoom room.', title: 'Zoom Room', required: [] })
  .openapi('ZoomRoom')

