export const putAccountsAccountIdPlansAddonsRoute = createRoute({
  method: 'put',
  path: '/accounts/{accountId}/plans/addons',
  tags: ['Billing'],
  summary: 'Update an additional plan',
  description:
    "Update an additional plan for a sub account.\n\nThis API can only be used by master accounts that pay all billiing charges of their associated Pro or higher sub accounts. Zoom allows only [approved partners](https://marketplace.zoom.us/docs/api-reference/master-account-apis) to use master APIs and manage sub accounts' subscriptions. Email the partner programs team at **partner-success@zoom.us** for more details.<br><br>\n<br>**Prerequisites:**<br>\n* Pro or a higher plan with master account enabled.\n* The sub account must be a paid account. The billing charges for the sub account must be paid by the master account.<br><br>\n\n**Scopes**: `billing:master`<br>\n**[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Heavy`<br>\n\n\n ",
  operationId: 'accountPlanAddonUpdate',
  request: {
    params: z.object({
      accountId: z
        .string()
        .openapi({
          param: {
            description: 'The account ID.',
            in: 'path',
            name: 'accountId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              hosts: z.int().openapi({ description: 'Number of hosts for this plan.' }),
              type: z
                .string()
                .openapi({
                  description:
                    'Account <a href="https://marketplace.zoom.us/docs/api-reference/other-references/plans">plan type.</a>',
                }),
            })
            .openapi({ description: 'Account plan object.', required: ['type', 'hosts'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              hosts: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({ description: 'Number of hosts for this plan.' }),
              type: z
                .string()
                .openapi({
                  description:
                    'Account <a href="https://marketplace.zoom.us/docs/api-reference/other-references/plans">plan type.</a>',
                }),
            })
            .openapi({ description: 'Account plan object.', required: ['type', 'hosts'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        "**Error Code:** `200`<br>\nFree trial and VIP accounts can't update sub plans.<br>\nYou don’t have subscription for ({oldPlanCode}) yet.\n",
    },
    204: {
      description: '**HTTP Status Code:** `204`<br>\nAdditional plan updated for the account.',
    },
    300: {
      description:
        '**Error Code:** `300`<br>\nPlan types do not match, oldPlanType: {oldPlanType} newPlanType: {newPlanType}.',
    },
    400: {
      description:
        '**HTTP Status Code:** `400`<br>\n**Error Code:** `2100`\n<br>This sub account is on self pay mode.\n<br>Invalid Additional Plan Type: {newPlanCode}.\n<br>Cannot update Additional plan for a sub account under free plan.\n<br>Invalid plan type.\n<br>Account can’t buy this product.\n<br>Can not subscribe/update additional Audio Conferencing Pay As You Go Plan for a sub account whose base plan is not Business/Education plan.<br>\nMaster accounts with bulk licenses cannot provision, update, or cancel plans for sub accounts using APIs, please use the billing portal or contact Support.<br>\n**Error Code:** `3261`<br>\nFailed to change sub plan of account:{accountId}.<br>\nMust subscribe to a major plan first.\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404`<br>\n**Error Code:** `2001`<br>\nAccount does not exist: {subAccountId}.<br>\n**Error Code:** `3200`<br>\nCannot find Zuora subscription for account:{subAccountId}.\n',
    },
  },
})

