export const deleteAccountsAccountIdSipTrunkInternalNumbersNumberIdRoute = createRoute({
  method: 'delete',
  path: '/accounts/{accountId}/sip_trunk/internal_numbers/{numberId}',
  tags: ['SIP Connected Audio'],
  summary: 'Delete an internal number',
  description:
    'This API allows a master account with SIP Connected Audio plan to delete a previously assigned internal phone number from a master account or a sub account.<br><br>To delete an internal number from a sub account, provide the account ID of the sub account in the `accountId` path parameter. To delete an internal number from a master account, provide `me` as the value of the `accountId` path parameter.\n<br><b>Prerequisites:</b><br>\n* The account making this API request must be a [master account](https://marketplace.zoom.us/docs/api-reference/master-account-apis) with SIP Connected Audio Plan.<br><br>\n**Scope:** `sip_trunk:master`\n\n\n',
  operationId: 'deleteInternalNumber',
  request: {
    params: z.object({
      accountId: z
        .string()
        .openapi({
          param: {
            description:
              'Unique Identifier of the account. To delete an internal number from a sub account, provide the account ID of the sub account in the `accountId` path parameter. To delete an internal number from a master account, provide `me` as the value of the `accountId` path parameter.',
            in: 'path',
            name: 'accountId',
            required: true,
            schema: { type: 'string' },
          },
        }),
      numberId: z
        .string()
        .openapi({
          param: {
            description:
              'Unique identifier of the phone number. This value can be retrieved by calling the List Internal Numbers API.',
            in: 'path',
            name: 'numberId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    204: {
      description: '**HTTP Status Code:** `204` **No Content** <br>\nNumber deleted.',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br>\n**Error Code:** `300`<br> \n* Your account does not have the permission to make updates on this account. Only a master account can perform this action on a sub account.\n* Request failed because this account is not enrolled in SIP Connected Audio plan.\n* This account is not a master account. To get access to this API, your account must be enrolled in the API Partner Plan and must be a master account.\n\n\n\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br>\n**Error Code:** `2001`<br> Account does not exist: {0}.',
    },
  },
})

export const postAccountsAccountIdSipTrunkNumbersRoute = createRoute({
  method: 'post',
  path: '/accounts/{accountId}/sip_trunk/numbers',
  tags: ['SIP Connected Audio'],
  summary: 'Assign numbers',
  description:
    "With SIP-connected audio, Zoom establishes a SIP trunk (a network connection specifically designed to make and deliver phone calls) over a direct and private connection between the customer’s network and the Zoom cloud. Meeting participants that dial into a meeting or have the meeting call them, and are On-Net from the perspective of the customers' IP telephony network, will be connected over this trunk rather than over the PSTN. <br><br>Use this API to assign internal numbers to a sub account.\n\n**Prerequisites:**<br>\n* Pro or a higher account with SIP Connected Audio plan enabled.\n* The account must be a master account<br>\n**Scopes:** `sip_trunk:master`<br> \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\n",
  operationId: 'assignSipTrunkNumbers',
  request: {
    params: z.object({
      accountId: z
        .string()
        .openapi({
          param: {
            description: 'Unique Identifier of the sub account.',
            in: 'path',
            name: 'accountId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              phone_numbers: z
                .array(z.string())
                .exactOptional()
                .openapi({ description: 'Phone number(s) to be assigned to the sub account.' }),
            })
            .openapi({ required: [] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              phone_numbers: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string()),
                )
                .exactOptional()
                .openapi({ description: 'Phone number(s) to be assigned to the sub account.' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: '**HTTP Status Code:** `201` **Created**<br>\nNumbers assigned successfully.\n',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br>\n**Error Code:** `2100`<br>\nThis sub account has no sip trunk plan.<br><br>\n**Error Code:** `400`<br>\nThis number does not belong to master account.\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br><br>\n**Error Code:** `2001`<br>\nThis account does not exist or does not belong to this master account.<br>\nThis account does not exist or does not belong to you.\n',
    },
  },
  security: [{ OAuth: [] }],
})

