export const postGroupsRoute = createRoute({
  method: 'post',
  path: '/groups',
  tags: ['Groups'],
  summary: 'Create a group',
  description:
    'Create a [group](https://support.zoom.us/hc/en-us/articles/204519819-Group-Management-) under an account. \n\nYou can add a maximum of 100 groups in one account per day. If you go over, you will get an error. You can add a maximum of 5000 groups in one account.\n\n**Prerequisite**: Pro or higher account.<br>\n**Scopes**: `group:write:admin`<br>\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`',
  operationId: 'groupCreate',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({ name: z.string().exactOptional().openapi({ description: 'Group name.' }) })
            .openapi({ required: [] }),
        },
        'multipart/form-data': {
          schema: z
            .object({ name: z.string().exactOptional().openapi({ description: 'Group name.' }) })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: '**Error Code:** `200`<br>\nOnly available for Paid account,{accountId}' },
    201: {
      description: '**HTTP Status Code:** `201`<br>\nGroup created.',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z.string().exactOptional().openapi({ description: 'Group ID.' }),
              name: z.string().exactOptional().openapi({ description: 'Group name.' }),
              total_members: z
                .int()
                .exactOptional()
                .openapi({ description: 'Group member count.' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: { value: { id: 'string', name: 'string', total_members: 'integer' } },
          },
        },
        'application/xml': {
          schema: z
            .object({
              id: z.string().exactOptional().openapi({ description: 'Group ID.' }),
              name: z.string().exactOptional().openapi({ description: 'Group name.' }),
              total_members: z
                .int()
                .exactOptional()
                .openapi({ description: 'Group member count.' }),
            })
            .openapi({ required: [] }),
        },
      },
      headers: z.object({
        'Content-Location': {
          description: 'Location of created group',
          schema: z
            .string()
            .exactOptional()
            .openapi({ description: 'Location of created group', param: { required: false } }),
        },
      }),
    },
    300: { description: '**Error Code:** `300`<br>\nMissing field: name.' },
    404: {
      description:
        '**HTTP Status Code:** `404`<br>**Error Code:** `4130`<br>A group with this {groupId} does not exist.\n\n\n\n',
    },
    409: {
      description:
        '**HTTP Status Code:** `409`<br> **Error Code:** `4132`<br> Group name {groupName} is already in use.',
    },
    429: {
      description:
        '**HTTP Status Code:** `429`<br>\nYou have exceeded the daily rate limit ({0}) of Create a Group API request for this account. This limit resets at GMT 00:00:00.',
    },
  },
  security: [{ OAuth: [] }],
})

