export const patchGroupsGroupIdRoute = createRoute({
  method: 'patch',
  path: '/groups/{groupId}',
  tags: ['Groups'],
  summary: 'Update a group',
  description:
    'Update a [group](https://support.zoom.us/hc/en-us/articles/204519819-Group-Management-) under your account.\n\n**Prerequisite**: Pro, Business, or Education account<br>\n**Scopes**: `group:write:admin`<br>\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`',
  operationId: 'groupUpdate',
  request: {
    params: z.object({
      groupId: z
        .string()
        .openapi({
          param: {
            description:
              'The group ID.<br>\nCan be retrieved by calling [GET /groups](https://marketplace.zoom.us/docs/api-reference/zoom-api/groups/groups).',
            in: 'path',
            name: 'groupId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Group name. It must be unique to one account and less than 128 characters.',
                }),
            })
            .openapi({ required: [] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Group name. It must be unique to one account and less than 128 characters.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: 'The group does not belong to this account:{accountId}.' },
    204: { description: 'Group updated.' },
    404: {
      description:
        '**Status Code:** `404`<br>\nNot found.<br>\n**Error Code:** `4130`<br>\nA group with this {groupId} does not exist.',
    },
    409: {
      description:
        '**Status Code:** `409`<br>\nConflict<br>\n**Error Code:** `4132`<br>\nGroup name {groupName} is already in use.',
    },
  },
  security: [{ OAuth: [] }],
})

