export const patchGroupsGroupIdMembersMemberIdRoute = createRoute({
  method: 'patch',
  path: '/groups/{groupId}/members/{memberId}',
  tags: ['Groups'],
  summary: 'Update a group member',
  description:
    "If a user is a member in multiple groups, you can [set a primary group](https://support.zoom.us/hc/en-us/articles/204519819-Group-Management-#h_d07c7dcd-4fd8-485a-b5fe-a322e8d21c09) for the user. The group member will use the primary group's settings by default. However, if settings are locked in other groups, those settings will continue to be locked for that user. By default, the primary group is the first group that user is added to.<br><br>\nUse this API to perform either of the following tasks:\n* Simultaneously remove a member from one group and move the member to a different group.\n* Set a primary group for the user<br><br>\n**Prerequisites:** \n* Pro or higher account<br> **Scopes:** `group:write:admin`\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Medium`",
  operationId: 'updateAGroupMember',
  request: {
    params: z.object({
      groupId: z
        .string()
        .openapi({
          param: {
            description:
              "Unique Identifier of the group. Can be retrieved by calling [GET /groups](https://marketplace.zoom.us/docs/api-reference/zoom-api/groups/groups) API.<br> To change a member's primary group, provide the groupId of the member's current primary group as the value of this field.<br> To remove a member from one group and move the member to another group, provide the groupId of the group from which the member is to be moved.",
            in: 'path',
            name: 'groupId',
            required: true,
            schema: { type: 'string' },
          },
        }),
      memberId: z
        .string()
        .openapi({
          param: {
            description:
              'Unique Identifier of the group member. Can be retrieved by calling the [List Group Members](https://marketplace.zoom.us/docs/api-reference/zoom-api/groups/groupmembers) API.',
            in: 'path',
            name: 'memberId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .enum(['move', 'set_primary'])
                .openapi({
                  description:
                    'Specify the type of action to be performed:<br><br>\n`move`: Simultaneously remove a member from one group and move the member to a different group.<br>\n`set_primary`: Set a primary group for the user.\n',
                }),
              target_group_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Can be retrieved by calling [GET /groups](https://marketplace.zoom.us/docs/api-reference/zoom-api/groups/groups) API.<br>\n\nTo move a user, use this field to specify the groupId of the group where the member is to be moved.<br>\n\nTo set a primary group for the user, provide the groupId of the group which is going to be the primary group.',
                }),
            })
            .openapi({ required: ['action'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              action: z
                .enum(['move', 'set_primary'])
                .openapi({
                  description:
                    'Specify the type of action to be performed:<br><br>\n`move`: Simultaneously remove a member from one group and move the member to a different group.<br>\n`set_primary`: Set a primary group for the user.\n',
                }),
              target_group_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Can be retrieved by calling [GET /groups](https://marketplace.zoom.us/docs/api-reference/zoom-api/groups/groups) API.<br>\n\nTo move a user, use this field to specify the groupId of the group where the member is to be moved.<br>\n\nTo set a primary group for the user, provide the groupId of the group which is going to be the primary group.',
                }),
            })
            .openapi({ required: ['action'] }),
        },
      },
    },
  },
  responses: {
    204: {
      description: '**HTTP Status Code:** `204` **No Content**<br>\nGroup member updated.',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br>\n**Error Code:** `200`<br>\n Only available for Paid account, {accountId}.<br><br>\n **Error Code:** `300`<br>\n The target_group_id can not be empty.<br><br>\n **Error Code:** `1010`<br>\n Group does not belong to this account:{accountId}.\n\n\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br>\n**Error Code:** `4130`<br>\nA group with this {groupId} does not exist.',
    },
  },
  security: [{ OAuth: [] }],
})

