export const postImChatMessagesRoute = createRoute({
  method: 'post',
  path: '/im/chat/messages',
  tags: ['Chatbot Messages'],
  summary: 'Send chatbot messages',
  description:
    'Send chatbot messages from your marketplace chatbot app.<br><br>\n**Scopes:** `imchat:bot`<br>\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Medium`<br>\n**Authorization Flow**: Client Credentials Flow<br><br>\nTo get authorized, make a POST request to `/oauth/token` endpoint with grant type as `client_credentials`. <br>Use `https://api.zoom.us/oauth/token?grant_type=client_credentials` as the endpoint for the request. \nYou will need to send your ClientID and Secret as a Basic base64 encoded AUthorization header. Ex. `Basic base64Encode({client_id}:{client_sceret})`<br><br> Next, use the token recieved (access_token) as a bearer token while making the POST /im/chat/messages request to send chatbot messages.<br><br>\nLearn more about how to authorize chatbots in the [Chatbot Authorization](https://marketplace.zoom.us/docs/guides/chatbots/authorization) guide.',
  operationId: 'sendchatbot',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              account_id: z
                .string()
                .openapi({ description: 'Account ID of the authorized account.' }),
              content: z
                .object({})
                .openapi({
                  description:
                    'JSON template describing how the message should be displayed for the user. For more information please see our ["Send Message" templates](https://marketplace.zoom.us/docs/guides/chatbots/sending-messages#example-request).',
                }),
              is_markdown_support: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    '**Optional**<br>\nApplies the markdown parser to your chatbot message if the value of this field is set to `true`.<br> To learn more, refer to the Chatbot message [markdown reference](https://marketplace.zoom.us/docs/guides/chatbots/customizing-messages/message-with-markdown).',
                }),
              robot_jid: z
                .string()
                .openapi({
                  description:
                    'Robot JID created when enabling chatbot features on your marketplace app.',
                }),
              to_jid: z
                .string()
                .openapi({ description: 'Unique JID of reciever. Can be a group or user.' }),
              user_jid: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '**Optional**<br>\nThe UserJID of the user on whose behalf the message is being sent. Use this field to prevent members of a channel from getting notifications that were set up by a user who has left the channel.',
                }),
              visible_to_user: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "**Optional**<br>Allow a Chatbot to send a message to a group channel, but have only one designated person in that group channel see the message by providing the person's UserID in this field.",
                }),
            })
            .openapi({ required: ['robot_jid', 'to_jid', 'account_id', 'content'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              account_id: z
                .string()
                .openapi({ description: 'Account ID of the authorized account.' }),
              content: z
                .object({})
                .openapi({
                  description:
                    'JSON template describing how the message should be displayed for the user. For more information please see our ["Send Message" templates](https://marketplace.zoom.us/docs/guides/chatbots/sending-messages#example-request).',
                }),
              is_markdown_support: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    '**Optional**<br>\nApplies the markdown parser to your chatbot message if the value of this field is set to `true`.<br> To learn more, refer to the Chatbot message [markdown reference](https://marketplace.zoom.us/docs/guides/chatbots/customizing-messages/message-with-markdown).',
                }),
              robot_jid: z
                .string()
                .openapi({
                  description:
                    'Robot JID created when enabling chatbot features on your marketplace app.',
                }),
              to_jid: z
                .string()
                .openapi({ description: 'Unique JID of reciever. Can be a group or user.' }),
              user_jid: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '**Optional**<br>\nThe UserJID of the user on whose behalf the message is being sent. Use this field to prevent members of a channel from getting notifications that were set up by a user who has left the channel.',
                }),
              visible_to_user: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "**Optional**<br>Allow a Chatbot to send a message to a group channel, but have only one designated person in that group channel see the message by providing the person's UserID in this field.",
                }),
            })
            .openapi({ required: ['robot_jid', 'to_jid', 'account_id', 'content'] }),
        },
      },
    },
  },
  responses: {
    200: { description: '**HTTP Status Code:** `200` **OK**<br>\nMessage Sent.' },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br>\n**Error Code:** `7001`<br>\nLink does not support markdown format.<br>\nEdit message does not support markdown format.',
    },
  },
  security: [{ Client_Credentials: [] }],
})

