export const patchMeetingsMeetingIdLivestreamRoute = createRoute({
  method: 'patch',
  path: '/meetings/{meetingId}/livestream',
  tags: ['Meetings'],
  summary: 'Update a live stream',
  description:
    "Zoom allows users to [live stream a meeting](https://support.zoom.us/hc/en-us/articles/115001777826-Live-Streaming-Meetings-or-Webinars-Using-a-Custom-Service) to a custom platform. Use this API to update a meeting's live stream information.<br><br>\n**Prerequisites:**<br>\n* Meeting host must have a Pro license.<br>\n**Scopes:** `meeting:write:admin` `meeting:write`<br>\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\n\n\n",
  operationId: 'meetingLiveStreamUpdate',
  request: {
    params: z.object({
      meetingId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The meeting ID in **long** format. The data type of this field is "long"(represented as int64 in JSON).\n\nWhile storing it in your database, store it as a **long** data type and **not as an integer**, as the Meeting IDs can be longer than 10 digits.',
            in: 'path',
            name: 'meetingId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      description: 'Meeting',
      content: {
        'application/json': {
          schema: z
            .object({
              page_url: z
                .url()
                .max(1024)
                .exactOptional()
                .openapi({ description: 'The livestream page URL.' }),
              stream_key: z.string().max(512).openapi({ description: 'Stream name and key.' }),
              stream_url: z.string().max(1024).openapi({ description: 'Streaming URL.' }),
            })
            .openapi({
              description: 'Meeting live stream.',
              required: ['stream_url', 'stream_key'],
            }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              page_url: z
                .url()
                .max(1024)
                .exactOptional()
                .openapi({ description: 'The livestream page URL.' }),
              stream_key: z.string().max(512).openapi({ description: 'Stream name and key.' }),
              stream_url: z.string().max(1024).openapi({ description: 'Streaming URL.' }),
            })
            .openapi({
              description: 'Meeting live stream.',
              required: ['stream_url', 'stream_key'],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: '**HTTP Status Code:** `204`<br>\nMeeting live stream updated.' },
    300: { description: '**Error Code:** `300` <br>Missing meetingId <br> Invalid meetingId.' },
    400: {
      description:
        '**HTTP Status Code:** `400`<br>**Error Code:** `1010` <br>\n User does not belong to this account: {accountId}.<br>\n **Error Code:** `3000` Cannot access webinar info.',
    },
    404: {
      description:
        '**HTTP Status Code:** `404`<br>**Error Code:** `1001` <br>User {userId} does not exist.\n',
    },
  },
  security: [{ OAuth: [] }],
})

export const patchMeetingsMeetingIdLivestreamStatusRoute = createRoute({
  method: 'patch',
  path: '/meetings/{meetingId}/livestream/status',
  tags: ['Meetings'],
  summary: 'Update Live Stream Status',
  description:
    "Zoom allows users to [live stream a meeting](https://support.zoom.us/hc/en-us/articles/115001777826-Live-Streaming-Meetings-or-Webinars-Using-a-Custom-Service) to a custom platform. Use this API to update the status of a meeting's live stream.<br><br>\n**Prerequisites:**<br>\n* Meeting host must have a Pro license.<br>\n**Scopes:** `meeting:write:admin` `meeting:write`<br>\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light` \n\n",
  operationId: 'meetingLiveStreamStatusUpdate',
  request: {
    params: z.object({
      meetingId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The meeting ID in **long** format. The data type of this field is "long"(represented as int64 in JSON).\n\nWhile storing it in your database, store it as a **long** data type and **not as an integer**, as the Meeting IDs can be longer than 10 digits.',
            in: 'path',
            name: 'meetingId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      description: 'Meeting',
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .enum(['start', 'stop'])
                .exactOptional()
                .openapi({
                  description:
                    'Update the status of a livestream.\n\nThe value can be one of the following:<br>\n`start`: Start a live stream. <br>\n`stop`: Stop an ongoing live stream.',
                  'x-enum-descriptions': [
                    'Start a meeting live stream.',
                    'Stop a meeting live stream.',
                  ],
                }),
              settings: z
                .object({
                  active_speaker_name: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description: 'Display the name of the active speaker during a live stream.',
                    }),
                  display_name: z
                    .string()
                    .min(1)
                    .max(50)
                    .exactOptional()
                    .openapi({ description: 'Display name of the live stream.' }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Update the settings of a live streaming session. The settings can only be updated for a live stream that has been stopped. You can not update the settings of an ongoing live stream.',
                  required: [],
                }),
            })
            .openapi({ description: 'Meeting live stream status.', required: [] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              action: z
                .enum(['start', 'stop'])
                .exactOptional()
                .openapi({
                  description:
                    'Update the status of a livestream.\n\nThe value can be one of the following:<br>\n`start`: Start a live stream. <br>\n`stop`: Stop an ongoing live stream.',
                  'x-enum-descriptions': [
                    'Start a meeting live stream.',
                    'Stop a meeting live stream.',
                  ],
                }),
              settings: z
                .object({
                  active_speaker_name: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      description: 'Display the name of the active speaker during a live stream.',
                    }),
                  display_name: z
                    .string()
                    .min(1)
                    .max(50)
                    .exactOptional()
                    .openapi({ description: 'Display name of the live stream.' }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Update the settings of a live streaming session. The settings can only be updated for a live stream that has been stopped. You can not update the settings of an ongoing live stream.',
                  required: [],
                }),
            })
            .openapi({ description: 'Meeting live stream status.', required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: '**HTTP Status Code:** `204` <br>\nMeeting live stream updated.\n\n' },
    300: { description: '**Error Code:** `300` <br>\nMissing meetingId.<br>\nInvalid meetingId' },
    400: {
      description:
        '**HTTP Status Code:** `400` <br>\n**Error Code:**`3000`<br>\nCannot access webinar info.<br>\n**Error Code:**`1010`<br>User does not belong to this account: {accountId}.\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` <br>\n**Error Code:**`1001`<br>\nUser {userId} does not exist.<br>\n',
    },
    429: {
      description:
        '**HTTP Status Code:** `429`<br>Too many requests submitted to start the live stream of this meeting: {meetingId}. If the live stream has not already started, retry making a new request after 30 seconds.',
    },
  },
  security: [{ OAuth: [] }],
})

