export const deleteMeetingsMeetingIdRecordingsRoute = createRoute({
  method: 'delete',
  path: '/meetings/{meetingId}/recordings',
  tags: ['Cloud Recording'],
  summary: 'Delete meeting recordings',
  description:
    "Delete all recording files of a meeting.<br><br>\n\n**Scopes:** `recording:write:admin` `recording:write`<br> \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`<br>\n**Prerequisites**:\n* Cloud Recording should be enabled on the user's account.<br>\n",
  operationId: 'recordingDelete',
  request: {
    params: z.object({
      meetingId: z
        .string()
        .openapi({
          param: {
            description:
              'To get Cloud Recordings of a meeting, provide the meeting ID or meeting UUID. If the meeting ID is provided instead of UUID,the response will be for the latest meeting instance. \n\nTo get Cloud Recordings of a webinar, provide the webinar ID or the webinar UUID. If the webinar ID is provided instead of UUID,the response will be for the latest webinar instance. \n\nIf a UUID starts with "/" or contains "//" (example: "/ajXp112QmuoKj4854875=="), you must **double encode** the UUID before making an API request. ',
            in: 'path',
            name: 'meetingId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      action: z
        .enum(['trash', 'delete'])
        .default('trash')
        .exactOptional()
        .openapi({
          param: {
            description:
              'The recording delete actions:<br>`trash` - Move recording to trash.<br>`delete` - Delete recording permanently.',
            in: 'query',
            name: 'action',
            schema: { default: 'trash', enum: ['trash', 'delete'], type: 'string' },
            'x-enum-descriptions': ['move recording to trash', 'delete recording permanently'],
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: '**Error Code:** `200` <br>\nYou do not have the right permission.' },
    204: { description: '**HTTP Status Code:** `204` <br>\nMeeting recording deleted.' },
    400: {
      description:
        '**HTTP Status Code:** `400`<br>\n**Error Code:** `1010`<br>\nUser does not belong to this account: {accountId}.',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` <br>\nMeeting recording not found\n**Error Code:** `1001` <br> User {userId} does not exist or does not belong to this account.<br>\n**Error Code:** `3301`<br>There is no recording for this meeting.\n',
    },
  },
  security: [{ OAuth: [] }],
})

