export const putMeetingsMeetingIdRecordingsRegistrantsStatusRoute = createRoute({
  method: 'put',
  path: '/meetings/{meetingId}/recordings/registrants/status',
  tags: ['Cloud Recording'],
  summary: "Update registrant's status",
  description:
    "A registrant can either be approved or denied from viewing the [on-demand](https://support.zoom.us/hc/en-us/articles/360000488283-On-demand-Recordings) recording. \nUse this API to update a registrant's status.\n\n**Scopes:** `recording:write:admin`, `recording:write`<br>\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Medium`\n",
  operationId: 'meetingRecordingRegistrantStatus',
  request: {
    params: z.object({
      meetingId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The meeting ID in **long** format. The data type of this field is "long"(represented as int64 in JSON).\n\nWhile storing it in your database, store it as a **long** data type and **not as an integer**, as the Meeting IDs can be longer than 10 digits.',
            in: 'path',
            name: 'meetingId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .enum(['approve', 'deny'])
                .openapi({ 'x-enum-descriptions': ['Approve registrant', 'Deny registrant'] }),
              registrants: z
                .array(z.object({ id: z.string().exactOptional() }).openapi({ required: [] }))
                .exactOptional()
                .openapi({ description: 'List of registrants' }),
            })
            .openapi({ description: 'Registrant Status', required: ['action'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              action: z
                .enum(['approve', 'deny'])
                .openapi({ 'x-enum-descriptions': ['Approve registrant', 'Deny registrant'] }),
              registrants: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.object({ id: z.string().exactOptional() }).openapi({ required: [] })),
                )
                .exactOptional()
                .openapi({ description: 'List of registrants' }),
            })
            .openapi({ description: 'Registrant Status', required: ['action'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: '**HTTP Status Code:** `204`<br>\nRegistrant status updated.' },
    404: {
      description: '**HTTP Status Code:** `404`<br>\nMeeting recording or Registrant not found',
    },
  },
  security: [{ OAuth: [] }],
})

