export const getMetricsMeetingsMeetingIdParticipantsSatisfactionRoute = createRoute({
  method: 'get',
  path: '/metrics/meetings/{meetingId}/participants/satisfaction',
  tags: ['Dashboards'],
  summary: 'Get post meeting feedback',
  description:
    'When a meeting ends, each attendee will be prompted to share their meeting experience by clicking either thumbs up or thumbs down. Use this API to retrieve the feedback submitted for a specific meeting. Note that this API only works for meetings scheduled after December 20, 2020.\n\n**Prerequisites:**\n* [Feedback to Zoom](https://support.zoom.us/hc/en-us/articles/115005838023) setting must be enabled by the participant prior to the meeting.\n* The user making the API request must be enrolled in a Business or a higher plan.\n\n<br> **Scope:** `dashboard_meetings:read:admiin`\n\n**[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Heavy`<br>',
  operationId: 'participantFeedback',
  request: {
    params: z.object({
      meetingId: z
        .string()
        .openapi({
          param: {
            description:
              'The meeting ID or the meeting UUID.  If a meeting ID is provided in the request instead of a UUID, the response will be for the latest meeting instance.\n\nIf a UUID starts with "/" or contains "//" (example: "/ajXp112QmuoKj4854875==\\"), you must **double encode** the UUID before making an API request.',
            in: 'path',
            name: 'meetingId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      type: z
        .enum(['past', 'pastOne', 'live'])
        .default('live')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Specify a value to get the response for the corresponding meeting type. The value of this field can be one of the following:<br> <br>`past` - Meeting that already occurred in the specified date range.<br>`pastOne` - Past meetings that were attended by only one user. <br>`live` - Live meetings.<br><br>\n\nIf you do not provide this field, the default value will be `live` and thus, the API will only query responses for live meetings.',
            in: 'query',
            name: 'type',
            schema: { default: 'live', enum: ['past', 'pastOne', 'live'], type: 'string' },
            'x-enum-descriptions': ['past meetings', 'past one user meetings', 'live meetings'],
            required: false,
          },
        }),
      next_page_token: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The next page token is used to paginate through large result sets. A next page token will be returned whenever the set of available results exceeds the current page size. The expiration period for this token is 15 minutes.',
            in: 'query',
            name: 'next_page_token',
            schema: { type: 'string' },
            required: false,
          },
        }),
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().max(300),
        )
        .default(30)
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of records returned within a single API call.',
            in: 'query',
            name: 'page_size',
            schema: { default: 30, maximum: 300, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '**HTTP Status Code:** `200`<br>\n\n',
      content: {
        'application/json': {
          schema: z
            .object({
              next_page_token: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The next page token is used to paginate through large result sets. A next page token will be returned whenever the set of available results exceeds the current page size. The expiration period for this token is 15 minutes.',
                }),
              page_size: z
                .int()
                .exactOptional()
                .openapi({
                  description: 'The number of records returned within a single API call.',
                }),
              participants: z
                .array(
                  z
                    .object({
                      date_time: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'Date and time at which the feedback was submitted.',
                        }),
                      email: z
                        .email()
                        .exactOptional()
                        .openapi({ description: 'Email address of the participant.' }),
                      quality: z
                        .enum(['GOOD', 'NOT GOOD'])
                        .exactOptional()
                        .openapi({
                          description:
                            'Feedback submitted by the participant. \n\n* `GOOD`: Thumbs up.\n* `NOT GOOD`: Thumbs down.',
                        }),
                      user_id: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'User ID of the participant.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                next_page_token: '',
                page_size: 1,
                participants: [
                  {
                    date_time: '2021-02-21T18:48:06.423Z',
                    email: 'RB6iBb@aWlMmuZFPVjptyOCzNgpi.mx',
                    quality: 'GOOD',
                    user_id: 'aegr46312rum',
                  },
                ],
              },
            },
          },
        },
        'application/xml': {
          schema: z
            .object({
              next_page_token: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The next page token is used to paginate through large result sets. A next page token will be returned whenever the set of available results exceeds the current page size. The expiration period for this token is 15 minutes.',
                }),
              page_size: z
                .int()
                .exactOptional()
                .openapi({
                  description: 'The number of records returned within a single API call.',
                }),
              participants: z
                .array(
                  z
                    .object({
                      date_time: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({
                          description: 'Date and time at which the feedback was submitted.',
                        }),
                      email: z
                        .email()
                        .exactOptional()
                        .openapi({ description: 'Email address of the participant.' }),
                      quality: z
                        .enum(['GOOD', 'NOT GOOD'])
                        .exactOptional()
                        .openapi({
                          description:
                            'Feedback submitted by the participant. \n\n* `GOOD`: Thumbs up.\n* `NOT GOOD`: Thumbs down.',
                        }),
                      user_id: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'User ID of the participant.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: {
      description:
        '**HTTP Status Code:** `400`<br>\n**Error Code:** `200`<br>\nOnly available for paid accounts that have dashboard feature enabled.\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404`<br>\n**Error Code:** `3001`<br>\nMeeting ID is invalid or not end.',
    },
  },
})

