export const getPastMeetingsMeetingIdFilesRoute = createRoute({
  method: 'get',
  path: '/past_meetings/{meetingId}/files',
  tags: ['Deprecated API Endpoints'],
  summary: "List past meeting's files",
  description:
    '**Note: This API has been deprecated and is no longer supported due to GCM encryption updates for security purposes.** To learn about saving the in-meeting chat files via Zoom Client, refer to the [Saving in-meeting chat](https://support.zoom.us/hc/en-us/articles/115004792763-Saving-in-meeting-chat) guide.\n\nList files sent via in-meeting chat during a meeting. The in-meeting files are deleted after 24 hours of the meeting completion time. \n<br><br>\n**Scope:** `meeting:read`, `meeting:read:admin`<br>\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Medium` ',
  operationId: 'listPastMeetingFiles',
  request: {
    params: z.object({
      meetingId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The meeting ID in **long** format. The data type of this field is "long"(represented as int64 in JSON).\n\nWhile storing it in your database, store it as a **long** data type and **not as an integer**, as the Meeting IDs can be longer than 10 digits.',
            in: 'path',
            name: 'meetingId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '**HTTP Status Code:** `200` **OK**<br>\nFiles retrieved successfully.',
      content: {
        'application/json': {
          schema: z
            .object({
              in_meeting_files: z
                .array(
                  z
                    .object({
                      download_url: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'URL to download the file.' }),
                      file_name: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Name of the file.' }),
                      file_size: z
                        .int()
                        .exactOptional()
                        .openapi({ description: 'Size of the file in bytes.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
              total_records: z
                .int()
                .exactOptional()
                .openapi({ description: 'The total number of files found.' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                in_meeting_files: [
                  {
                    download_url: 'somefile.txt/randomurl',
                    file_name: 'somefile.txt',
                    file_size: 300,
                  },
                ],
                total_records: 1,
              },
            },
          },
        },
        'application/xml': {
          schema: z
            .object({
              in_meeting_files: z
                .array(
                  z
                    .object({
                      download_url: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'URL to download the file.' }),
                      file_name: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Name of the file.' }),
                      file_size: z
                        .int()
                        .exactOptional()
                        .openapi({ description: 'Size of the file in bytes.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
              total_records: z
                .int()
                .exactOptional()
                .openapi({ description: 'The total number of files found.' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: {
      description:
        '**HTTP Status Code:** `400`<br>\n**Error Code:** `1010`<br>\nUser does not belong to this account: {accountId}.',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br>\n**Error Code:** `3001`<br>\nMeeting ID is invalid or not end.',
    },
  },
  security: [{ OAuth: [] }],
})

