export const getPastWebinarsWebinarIdInstancesRoute = createRoute({
  method: 'get',
  path: '/past_webinars/{webinarId}/instances',
  tags: ['Webinars'],
  summary: 'List past webinar instances',
  description:
    'List past webinar instances.<br><br>\n**Scopes:** `webinar:read:admin` `webinar:read`<br>\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`<br>\n\n',
  operationId: 'pastWebinars',
  request: {
    params: z.object({
      webinarId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The webinar ID in "**long**" format(represented as int64 data type in JSON). ',
            in: 'path',
            name: 'webinarId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '**HTTP Status Code:** `200`<br>\nList of past webinar instances returned.',
      content: {
        'application/json': {
          schema: z
            .object({
              webinars: z
                .array(
                  z
                    .object({
                      start_time: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({ description: 'Start time.' }),
                      uuid: z.string().exactOptional().openapi({ description: 'Webinar UUID.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({ description: 'List of ended webinar instances.' }),
            })
            .openapi({ required: [] })
            .openapi({ description: 'List of webinars.', title: 'Webinar instances' }),
          examples: {
            response: {
              value: {
                webinars: [{ start_time: '2019-06-07T03:42:34.548Z', uuid: 'ut44544gisi' }],
              },
            },
          },
        },
        'application/xml': {
          schema: z
            .object({
              webinars: z
                .array(
                  z
                    .object({
                      start_time: z.iso
                        .datetime({ offset: true })
                        .exactOptional()
                        .openapi({ description: 'Start time.' }),
                      uuid: z.string().exactOptional().openapi({ description: 'Webinar UUID.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({ description: 'List of ended webinar instances.' }),
            })
            .openapi({ required: [] })
            .openapi({ description: 'List of webinars.', title: 'Webinar instances' }),
        },
      },
    },
    300: { description: '**HTTP Status Code:** `300`<br>\nInvalid webinar ID.' },
    404: { description: '**HTTP Status Code:** `404`<br>\nWebinar not found.' },
  },
  security: [{ OAuth: [] }],
})

