export const patchPhoneCallQueuesCallQueueIdRoute = createRoute({
  method: 'patch',
  path: '/phone/call_queues/{callQueueId}',
  tags: ['Phone Call Queues'],
  summary: 'Update call queue details',
  description:
    'Call queues allow you to route incoming calls to a group of users. For instance, you can use call queues to route calls to various departments in your organization such as sales, engineering, billing, customer service etc.<br> Use this API to update information of a specific Call Queue.<br> \n**Prerequisites:**<br>\n* Pro, Business, or Education account\n* Account owner or admin permissions\n* Zoom Phone license<br>\n**Scopes:** `phone:write:admin`<br> \n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\n',
  operationId: 'updateCallQueue',
  request: {
    params: z.object({
      callQueueId: z
        .string()
        .openapi({
          param: {
            description: 'Unique Identifier of the Call Queue.',
            in: 'path',
            name: 'callQueueId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              description: z
                .string()
                .max(32)
                .exactOptional()
                .openapi({ description: 'Description for the Call Queue.' }),
              extension_number: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'Phone extension number for the site.<br>\n\nIf a site code has been [assigned](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-Multiple-Sites#h_79ca9c8f-c97b-4486-aa59-d0d9d31a525b) to the site, provide the short extension number instead of the original extension number.',
                }),
              name: z
                .string()
                .max(32)
                .exactOptional()
                .openapi({ description: 'Name of the Call Queue.' }),
              site_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifier of the [site](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-Multiple-Sites) where the Call Queue is assigned.',
                }),
              status: z
                .enum(['active', 'inactive'])
                .exactOptional()
                .openapi({
                  description:
                    'Status of the Call Queue. Allowed values:<br>\n`active`<br>\n`inactive`',
                }),
              timezone: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '[Timezone](https://marketplace.zoom.us/docs/api-reference/other-references/abbreviation-lists#timezones) of the Call Queue.',
                }),
            })
            .openapi({ required: [] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              description: z
                .string()
                .max(32)
                .exactOptional()
                .openapi({ description: 'Description for the Call Queue.' }),
              extension_number: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Phone extension number for the site.<br>\n\nIf a site code has been [assigned](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-Multiple-Sites#h_79ca9c8f-c97b-4486-aa59-d0d9d31a525b) to the site, provide the short extension number instead of the original extension number.',
                }),
              name: z
                .string()
                .max(32)
                .exactOptional()
                .openapi({ description: 'Name of the Call Queue.' }),
              site_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifier of the [site](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-Multiple-Sites) where the Call Queue is assigned.',
                }),
              status: z
                .enum(['active', 'inactive'])
                .exactOptional()
                .openapi({
                  description:
                    'Status of the Call Queue. Allowed values:<br>\n`active`<br>\n`inactive`',
                }),
              timezone: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '[Timezone](https://marketplace.zoom.us/docs/api-reference/other-references/abbreviation-lists#timezones) of the Call Queue.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    204: {
      description:
        '**HTTP Status Code:** `204` **No Content**<br>\nCall Queue details updated successfully.',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br>\n**Error Code:** `300`<br>\nValidation Failed. The group does not exist, groupId:{groupId}<br>\nTimezone not found in the system.<br><br>\n**Error Code:** `400`<br>\nUnable to update this call queue as it is used for internal safety response team.',
    },
  },
  security: [{ OAuth: [] }],
})

