export const postPhoneCommonAreaPhonesRoute = createRoute({
  method: 'post',
  path: '/phone/common_area_phones',
  tags: ['Common Area Phones'],
  summary: 'Add a common area phone',
  description:
    "A common area phone can be provisioned by a Zoom account owner or a Zoom admin so that anyone in an organization can use it. For example, if your office has shared desks that don't belong to a specific employees, you could add a common area phone so that any person can use it.<br> Use this API to [add a common area phone](https://support.zoom.us/hc/en-us/articles/360028516231-Managing-Common-Area-Phones#h_2d0da347-c35a-4993-9771-e21aaa568deb).<br><br>\n**Prerequisites:**<br>\n* Pro or a higher account with Zoom Phone license.\n* Account owner or admin permissions.\n* [Supported device](https://support.zoom.us/hc/en-us/articles/360001299063-Zoom-Voice-Supported-Devices)<br>\n**Scope:** `phone:write:admin`<br> \n\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`",
  operationId: 'addCommonAreaPhone',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'Description for the common area phone.' }),
              display_name: z
                .string()
                .openapi({ description: 'Display name of the Common area phone.' }),
              extension_number: z
                .int()
                .openapi({
                  description:
                    'Extension number assigned to the common area phone. If site code is enabled, provide the short extension number instead.',
                }),
              mac_address: z
                .string()
                .openapi({
                  description:
                    'Mac Address (serial number) of the common area desk phone. These examples show the formats supported: `64-16-7f-37-90-92` or `64167f379092`',
                }),
              model: z
                .string()
                .min(1)
                .max(50)
                .exactOptional()
                .openapi({
                  description:
                    'Device Model name. Refer to the "Model Name" field in [this](https://marketplace.zoom.us/docs/api-reference/other-references/zoomphone-supporteddevice) table.',
                }),
              site_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifier of the [site](https://support.zoom.us/hc/en-us/articles/360020809672). This can be retrieved from the [List Phone Sites](https://marketplace.zoom.us/docs/api-reference/zoom-api/phone-site/listphonesites) API.',
                }),
              time_zone: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '[Timezone ID](https://marketplace.zoom.us/docs/api-reference/other-references/abbreviation-lists) for the common area phone.',
                }),
              type: z
                .string()
                .min(1)
                .max(50)
                .openapi({
                  description:
                    'Phone device manufacturer name. Refer to the "Manufacturer Name" field in [this](https://marketplace.zoom.us/docs/api-reference/other-references/zoomphone-supporteddevice) table.',
                }),
            })
            .openapi({ required: ['display_name', 'extension_number', 'mac_address', 'type'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description:
        '**HTTP Status Code:** `201` **Created**<br>\n\nCommon area phone added successfully.',
      content: {
        'application/json': {
          schema: z
            .object({
              display_name: z
                .string()
                .exactOptional()
                .openapi({ description: 'Display name of the common area phone.' }),
              id: z
                .string()
                .exactOptional()
                .openapi({ description: 'Unique Identifier of the common area phone.' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: { value: { display_name: 'Common Area Phone - lobby', id: 'comfgfd45um' } },
          },
        },
        'application/xml': {
          schema: z
            .object({
              display_name: z
                .string()
                .exactOptional()
                .openapi({ description: 'Display name of the common area phone.' }),
              id: z
                .string()
                .exactOptional()
                .openapi({ description: 'Unique Identifier of the common area phone.' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br><br>\n**Error Code:** `300`<br>\nValidation failed.<br>\n* Phone manufacturer does not exist.\n* Phone model does not exist.\n* Phone manufacturer is not supported.<br><br>\n**Error Code:** `400`<br>\nThe MAC Address is invalid.\n',
    },
    409: {
      description:
        '**HTTP Status Code:** `409`<br>\n**Error Code:** `409`<br>\nThe MAC Address already exists in the system.',
    },
  },
  security: [{ OAuth: [] }],
})

