export const postPhoneDevicesRoute = createRoute({
  method: 'post',
  path: '/phone/devices',
  tags: ['Phone Devices'],
  summary: 'Add a device',
  description:
    'By default, all Zoom Phone users can make and receive calls using the Zoom desktop and mobile applications. Additionally, if a desk phone is required, use this API to [add a desk phone and assign it](https://support.zoom.us/hc/en-us/articles/360021119092#h_5ca07504-68a8-4c3d-ad0e-c1d3594436da) to a user.\n\n**Prerequisites:**<br>\n* Pro or a higher account with Zoom Phone license\n* Account owner or admin permissions\n* [Supported device](https://support.zoom.us/hc/en-us/articles/360001299063-Zoom-Voice-Supported-Devices)<br>\n**Scopes:** `phone:write:admin`<br> \n\n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`',
  operationId: 'addPhoneDevice',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              assigned_to: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'User ID or email address of the user to whom this device is to be assigned. The User ID and the email of the user can be retrieved using the [List Users](https://marketplace.zoom.us/docs/api-reference/zoom-api/users/users) API.',
                }),
              display_name: z
                .string()
                .max(255)
                .openapi({ description: 'Display name of the desk phone.' }),
              mac_address: z
                .string()
                .regex(/^([0-9A-Fa-f]{2}[:-]?){5}([0-9A-Fa-f]{2})$/)
                .openapi({
                  description:
                    "The MAC address of the desk phone.<br> \nNote: If you're using a wireless phone, enter the wired MAC address, not the wireless MAC address.",
                }),
              model: z
                .string()
                .max(50)
                .exactOptional()
                .openapi({ description: 'Model name of the device.' }),
              type: z
                .string()
                .max(50)
                .exactOptional()
                .openapi({ description: 'Manufacturer (brand) name of the device.' }),
            })
            .openapi({ required: ['mac_address', 'display_name'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              assigned_to: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'User ID or email address of the user to whom this device is to be assigned. The User ID and the email of the user can be retrieved using the [List Users](https://marketplace.zoom.us/docs/api-reference/zoom-api/users/users) API.',
                }),
              display_name: z
                .string()
                .max(255)
                .openapi({ description: 'Display name of the desk phone.' }),
              mac_address: z
                .string()
                .regex(/^([0-9A-Fa-f]{2}[:-]?){5}([0-9A-Fa-f]{2})$/)
                .openapi({
                  description:
                    "The MAC address of the desk phone.<br> \nNote: If you're using a wireless phone, enter the wired MAC address, not the wireless MAC address.",
                }),
              model: z
                .string()
                .max(50)
                .exactOptional()
                .openapi({ description: 'Model name of the device.' }),
              type: z
                .string()
                .max(50)
                .exactOptional()
                .openapi({ description: 'Manufacturer (brand) name of the device.' }),
            })
            .openapi({ required: ['mac_address', 'display_name'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: '**HTTP Status Code:** `201` **Created**<br>\nDevice added successfully.  ',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br>\n**Error Code:** `300` **Validation failed.**<br>\nPhone manufacturer does not exist.<br>\nPhone model does not exist.<br>\nPhone manufacturer is not supported.<br><br>\n**Error Code:** `400`<br>\nThe MAC Address is invalid.<br>\nThe MAC Address already exists in the system.<br>\nEach user can be assigned up to three desk phones.<br>\n',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br>\n**Error Code:** `1001`<br>\nUser not found: {userId}\n',
    },
  },
  security: [{ OAuth: [] }],
})

