export const postPhoneSharedLineGroupsRoute = createRoute({
  method: 'post',
  path: '/phone/shared_line_groups',
  tags: ['Phone Shared Line Groups'],
  summary: 'Create a shared line group',
  description:
    "A [shared line group](https://support.zoom.us/hc/en-us/articles/360038850792) allows Zoom Phone admins to share a phone number and extension with a group of phone users or common area phones. This gives members of the shared line group access to the group's direct phone number and voicemail. Use this API to create a shared line group.\n\n**Prerequisties:** <br>\n* Pro or higher account with Zoom Phone license.\n* Account owner or admin privileges \n\n**Scopes:** `phone:write:admin`\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`",
  operationId: 'createASharedLineGroup',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              description: z
                .string()
                .max(255)
                .exactOptional()
                .openapi({ description: 'Provide a description for the shared line group.' }),
              display_name: z
                .string()
                .max(200)
                .openapi({ description: 'Provide a name to help identify the shared line group.' }),
              extension_number: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'Extension number to be assigned to the shared line group. If a [site code has been assigned](https://support.zoom.us/hc/en-us/articles/360020809672#h_79ca9c8f-c97b-4486-aa59-d0d9d31a525b) to the site, provide the short extension number ',
                }),
              site_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifier of the [site](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-multiple-sites) that you would like to use for the shared line group. You will only be able to add members that belong to this site to the shared line group.\n\nThis field is required only if the [multiple sites](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-multiple-sites) option has been enabled for the account.',
                }),
            })
            .openapi({ required: ['display_name'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              description: z
                .string()
                .max(255)
                .exactOptional()
                .openapi({ description: 'Provide a description for the shared line group.' }),
              display_name: z
                .string()
                .max(200)
                .openapi({ description: 'Provide a name to help identify the shared line group.' }),
              extension_number: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Extension number to be assigned to the shared line group. If a [site code has been assigned](https://support.zoom.us/hc/en-us/articles/360020809672#h_79ca9c8f-c97b-4486-aa59-d0d9d31a525b) to the site, provide the short extension number ',
                }),
              site_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifier of the [site](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-multiple-sites) that you would like to use for the shared line group. You will only be able to add members that belong to this site to the shared line group.\n\nThis field is required only if the [multiple sites](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-multiple-sites) option has been enabled for the account.',
                }),
            })
            .openapi({ required: ['display_name'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        '**HTTP Status Code:** `200` **OK** <br>\nShared Line Group created successfully.\n',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request** <br>\n**Error Code:** `300` **Validation Failed** <br>\n* Multiple Site has not been enabled for this account.<br>\n* Site does not exist. <br><br>\n**Error Code:** `400` <br>\nExtension number {extensionNumber} is already used.<br><br>\n**Error Code:** `409` <br>\nInvalid short number length. <br>\nNumber {extensionNumber} is a reserved extension number.\n\n\n',
    },
  },
  security: [{ OAuth: [] }],
})

