export const deletePhoneSitesSiteIdRoute = createRoute({
  method: 'delete',
  path: '/phone/sites/{siteId}',
  tags: ['Phone Site'],
  summary: 'Delete a phone site',
  description:
    'Sites allow you to organize Zoom Phone users in your organization. Use this API to delete a specific [site](https://support.zoom.us/hc/en-us/articles/360020809672) in a Zoom account. To delete a site, in the query parameter, you must provide the Site ID of another site where the assets of current site (users, numbers and phones) can be transferred to.  You cannot use this API to delete the main site.\n\n**Prerequisites:** <br>\n* Account must have a Pro or a higher plan with Zoom Phone license. \n* [Multiple Sites](https://support.zoom.us/hc/en-us/articles/360020809672-Managing-Multiple-Sites) must be enabled.<br>\n**Scope:** `phone:write:admin`\n<br> \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\n\n',
  operationId: 'deletePhoneSite',
  request: {
    params: z.object({
      siteId: z
        .string()
        .openapi({
          param: {
            description: 'Unique Identifier of the Site.',
            in: 'path',
            name: 'siteId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      transfer_site_id: z
        .string()
        .openapi({
          param: {
            description:
              'The Site ID of another site where the assets of the current site (users, numbers and phones) can be transferred to.',
            in: 'query',
            name: 'transfer_site_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    204: {
      description: '**HTTP Status Code:** `204`<br>\nPhone Site deleted.',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request**<br><br>\n**Error Code:** `400`<br>\nUnable to transfer to the same site.<br>\nMain company number can not change {phoneNumber}.<br>\nSite does not exist.',
    },
    409: {
      description:
        '**HTTP Status Code:** `409` **Conflict**<br><br>\n**Error Code:** `409`<br>\nConflict target extension number, try later.',
    },
  },
  security: [{ OAuth: [] }],
})

