export const deletePhoneUsersUserIdCallLogsCallLogIdRoute = createRoute({
  method: 'delete',
  path: '/phone/users/{userId}/call_logs/{callLogId}',
  tags: ['Phone'],
  summary: "Delete a user's call log",
  description:
    "Delete a user's [call log](https://support.zoom.us/hc/en-us/articles/360021114452-Viewing-and-identifying-logs).\n\n**Scopes:** `phone:write`, `phone:write:admin`<br> \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`<br>\n\n**Prerequisites:** \n1. User must belong to a Business or an Enterprise account.\n2. User must hold a Zoom Phone license.",
  operationId: 'deleteCallLog',
  request: {
    params: z.object({
      userId: z
        .string()
        .openapi({
          param: {
            description: 'The user ID or email address of the user.',
            in: 'path',
            name: 'userId',
            required: true,
            schema: { type: 'string' },
          },
        }),
      callLogId: z
        .string()
        .openapi({
          param: {
            description:
              "Unique identifier of the call log. The value for this field can be retrieved from [account's call logs](https://marketplace.zoom.us/docs/api-reference/zoom-api/phone/accountcalllogs) or [user's call logs](https://marketplace.zoom.us/docs/api-reference/zoom-api/phone/phoneusercalllogs).",
            in: 'path',
            name: 'callLogId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    204: {
      description: '**HTTP Status Code**: `204` <br>\nLog deleted.\n',
      content: { 'application/json': { schema: z.any() }, 'application/xml': { schema: z.any() } },
    },
    401: {
      description:
        '**HTTP Status Code**: `404` <br>\n**Error Code**: `124` <br>\nAccount does not exist: {accountId}.',
    },
    404: {
      description:
        '**HTTP Status Code**: `404` <br>\nCall log information was not found for the following callLogId: {callLogId}.\n\n\n',
    },
  },
})

