export const deleteSipPhonesPhoneIdRoute = createRoute({
  method: 'delete',
  path: '/sip_phones/{phoneId}',
  tags: ['SIP Phone'],
  summary: 'Delete SIP phone',
  description:
    'Zoom’s Phone System Integration (PSI), also referred as SIP phones, enables an organization to leverage the Zoom client to complete a softphone registration to supported premise based PBX system. End users will have the ability to have softphone functionality within a single client while maintaining a comparable interface to Zoom Phone. Use this API to delete a specific SIP phone on a Zoom account.<br><br>\n**Prerequisites**:\n* Currently only supported on Cisco and Avaya PBX systems. \n* User must enable SIP Phone Integration by contacting the [Sales](https://zoom.us/contactsales) team.<br> **Scope:** `sip_phone:read:admin`\n<br> \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`',
  operationId: 'deleteSIPPhone',
  request: {
    params: z.object({
      phoneId: z
        .string()
        .openapi({
          param: {
            description:
              'Unique Identifier of the SIP Phone. It can be retrieved from the List SIP Phones API.',
            in: 'path',
            name: 'phoneId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        '**Error Code:** `200`<br>Permission missing: Enable SIP Phone Integration by contacting a Zoom Admin first.',
    },
    204: {
      description: '**HTTP Status Code:** `204`<br>\nSIP Phone deleted.',
      content: {
        'application/json': { schema: z.object({}) },
        'application/xml': { schema: z.object({}) },
      },
    },
    300: {
      description:
        '**Error Code:** `300`The SIP phone with this phoneId was not found on this account.',
    },
  },
  security: [{ OAuth: [] }],
})

