export const getSipTrunkNumbersRoute = createRoute({
  method: 'get',
  path: '/sip_trunk/numbers',
  tags: ['SIP Connected Audio'],
  summary: 'List SIP trunk numbers',
  description:
    "With SIP-connected audio, Zoom establishes a SIP trunk (a network connection specifically designed to make and deliver phone calls) over a direct and private connection between the customer’s network and the Zoom cloud. Meeting participants that dial into a meeting or have the meeting call them, and are On-Net from the perspective of the customers' IP telephony network, will be connected over this trunk rather than over the PSTN. <br><br>Use this API to list all the numbers that are configured for SIP Connected Audio in a Zoom Account.\n\n**Prerequisites:**<br>\n* Pro or a higher account with SIP Connected Audio plan enabled.\n* The account must be a master account<br>\n**Scopes:** `sip_trunk:master`\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`",
  operationId: 'listSipTrunkNumbers',
  responses: {
    200: {
      description: '* **HTTP Status Code:** `200` **OK**<br>\nList of numbers returned.',
      content: {
        'application/json': {
          schema: z
            .object({
              phone_numbers: z
                .array(
                  z
                    .object({
                      country: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Country ID (example: US)' }),
                      number: z.string().exactOptional().openapi({ description: 'Phone number' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
              total_records: z
                .int()
                .exactOptional()
                .openapi({ description: 'Total number of records returned.' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: { phone_numbers: [{ country: 'US', number: '45345545' }], total_records: 1 },
            },
          },
        },
        'application/xml': {
          schema: z
            .object({
              phone_numbers: z
                .array(
                  z
                    .object({
                      country: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Country ID (example: US)' }),
                      number: z.string().exactOptional().openapi({ description: 'Phone number' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
              total_records: z
                .int()
                .exactOptional()
                .openapi({ description: 'Total number of records returned.' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br><br>\n**Error Code:** `2001`<br>\nThis account does not exist or does not belong to this master account.\nThis account does not exist or does not belong to you.',
    },
  },
  security: [{ OAuth: [] }],
})

