export const deleteUsersUserIdRoute = createRoute({
  method: 'delete',
  path: '/users/{userId}',
  tags: ['Users'],
  summary: 'Delete a user',
  description:
    'Deleting a user permanently removes the user and their data from Zoom. Users can create a new Zoom account using the same email address. An account owner or an account admin can transfer meetings, webinars and cloud recordings to another Zoom user account before deleting.<br><br>\n\nThis API disassociates (unlinks) a user from the associated Zoom account and provides the user their own basic free Zoom account, and the user can purchase their own licenses. You can transfer the user\'s data (meetings, webinars and cloud recordings) to another user before disassociation.<br> To permanently delete a user, specify "delete" as the value of the `action` query parameter.\n**Scopes:** `user:write:admin` `user:write`<br>\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`',
  operationId: 'userDelete',
  request: {
    params: z.object({
      userId: z
        .string()
        .openapi({
          param: {
            description:
              'The user ID or email address of the user. For user-level apps, pass `me` as the value for userId.',
            in: 'path',
            name: 'userId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      action: z
        .enum(['disassociate', 'delete'])
        .default('disassociate')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Delete action options:<br>`disassociate` - Disassociate a user.<br>`delete`-  Permanently delete a user.<br>Note: To delete pending user in the account, use `disassociate`',
            in: 'query',
            name: 'action',
            schema: { default: 'disassociate', enum: ['disassociate', 'delete'], type: 'string' },
            'x-enum-descriptions': ['Disassociate a user', 'Permanently delete a user'],
            required: false,
          },
        }),
      transfer_email: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Transfer email.',
            in: 'query',
            name: 'transfer_email',
            required: false,
            schema: { type: 'string' },
          },
        }),
      transfer_meeting: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Transfer meeting.',
            in: 'query',
            name: 'transfer_meeting',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      transfer_webinar: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Transfer webinar.',
            in: 'query',
            name: 'transfer_webinar',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      transfer_recording: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Transfer recording.',
            in: 'query',
            name: 'transfer_recording',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    204: { description: '**HTTP Status Code:** `204`<br>\nUser deleted.' },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request** <br><br> **Error Code:** `300`<br>The transfer-to email address cannot be the same as the unlinked or deleted user’s email address.<br> Unable to unlink API user(s).<br><br>\n**Error Code:** `200`<br>Cannot delete a user out of your account. <br>Cannot delete a Zoom Rooms user. <br>Unable to delete this deactivated user. Please contact Zoom support team for more information. <br><br>\n**Error Code:** `1000`<br>\nThe user cannot be changed because they are a Call-queue manager or Auto-receptionist operator.<br><br>\n**Error Code:** `1107`<br>You can not disassociate a user with managed domain.<br><br>\n**Error Code:** `1117`<br>You can not disassociate an Admin user.<br><br>\n**Error Code:** `1120`<br>A valid invitation to join the Zoom account was not found for this user. <br>This error is thrown if you added a user in your account but the user did not accept the invitation on time and the invitation expired - thus making the userId invalid.',
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br><br>\n**Error Code:** `1001`<br>\nUser does not exist: $userId.<br>',
    },
  },
})

