export const postUsersUserIdSettingsVirtualBackgroundsRoute = createRoute({
  method: 'post',
  path: '/users/{userId}/settings/virtual_backgrounds',
  tags: ['Users'],
  summary: 'Upload virtual background files',
  description:
    'Use this API to [upload virtual background files](https://support.zoom.us/hc/en-us/articles/210707503-Virtual-Background) for a user. \n\n**Prerequisites:**<br>\n* Virtual background feature must be [enabled](https://support.zoom.us/hc/en-us/articles/210707503-Virtual-Background#h_2ef28080-fce9-4ac2-b567-dc958afab1b7) on the account.\n<br> **Scope:** `user:write:admin`\n**[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Medium`<br>\n\n',
  operationId: 'uploadVBuser',
  request: {
    params: z.object({
      userId: z
        .string()
        .openapi({
          param: {
            description:
              'Unique identifier of the user. Retrieve the value for this field by calling the [List users](https://marketplace.zoom.us/docs/api-reference/zoom-api/users/users) API.',
            in: 'path',
            name: 'userId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: UploadVBRequestBody,
  },
  responses: {
    201: {
      description: '**HTTP Status Code:** `201` **Created** <br>\n',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z
                .string()
                .exactOptional()
                .openapi({ description: 'Unique identifier of the file.' }),
              is_default: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Indicate whether or not this file is the default virtual background file.',
                }),
              name: z.string().exactOptional().openapi({ description: 'File name.' }),
              size: z.string().exactOptional().openapi({ description: 'File size.' }),
              type: z.string().exactOptional().openapi({ description: 'File type.' }),
            })
            .openapi({ required: [] }),
          examples: {
            response: {
              value: {
                id: '_Tcj7354w6eHw',
                is_default: false,
                name: 'u=mdbhhfg3y7&fm=2fdjs0.jpg',
                size: 53434,
                type: 'image',
              },
            },
          },
        },
        'application/xml': {
          schema: z
            .object({
              id: z
                .string()
                .exactOptional()
                .openapi({ description: 'Unique identifier of the file.' }),
              is_default: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Indicate whether or not this file is the default virtual background file.',
                }),
              name: z.string().exactOptional().openapi({ description: 'File name.' }),
              size: z.string().exactOptional().openapi({ description: 'File size.' }),
              type: z.string().exactOptional().openapi({ description: 'File type.' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: {
      description:
        '**HTTP Status Code:** `400` **Bad Request** <br>\n**Error Code:** `120`<br>\nNo file uploaded, verify that a file has been uploaded.<br>\nFile size cannot exceed 15M.<br>\nA maximum of 10 files are allowed for a user.<br>\nOnly jpg/jpeg, gif or png image file can be uploaded.\n\n',
    },
    404: { description: '**HTTP Status Code:** `404` **Not Found** <br>\nGroup not found.' },
  },
})

