export const putUsersUserIdStatusRoute = createRoute({
  method: 'put',
  path: '/users/{userId}/status',
  tags: ['Users'],
  summary: 'Update user status',
  description:
    'An account owner or admins can deactivate as well as activate a user in a Zoom account. Deactivating a user will remove all licenses associated with a user. It will prevent the deactivated user from logging into their Zoom account. A deactivated user can be reactivated. Reactivating a user grants the user access to login to their Zoom account.<br> Use this API to either [deactivate](https://support.zoom.us/hc/en-us/articles/115005269946-Remove-User-from-your-Account#h_6a9bc1c3-d739-4945-b1f2-00b3b88fb5cc) an active user or to [reactivate](https://support.zoom.us/hc/en-us/articles/115005269946-Remove-User-from-your-Account#h_16319724-d120-4be6-af5d-31582d134ea0) a deactivated user .<br><br>**Scopes:** `user:write:admin` `user:write`<br> \n\n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\n\n',
  operationId: 'userStatus',
  request: {
    params: z.object({
      userId: z
        .string()
        .openapi({
          param: {
            description:
              'The user ID or email address of the user. For user-level apps, pass `me` as the value for userId.',
            in: 'path',
            name: 'userId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      description: 'User status.',
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .enum(['activate', 'deactivate'])
                .openapi({
                  description:
                    'The action types:<br>`activate` - Activate a deactivated user.<br>`deactivate` - Deactivate a user.',
                  'x-enum-descriptions': [
                    'set users status to active',
                    'set users status to inactive',
                  ],
                }),
            })
            .openapi({ description: 'The action.', required: ['action'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              action: z
                .enum(['activate', 'deactivate'])
                .openapi({
                  description:
                    'The action types:<br>`activate` - Activate a deactivated user.<br>`deactivate` - Deactivate a user.',
                  'x-enum-descriptions': [
                    'set users status to active',
                    'set users status to inactive',
                  ],
                }),
            })
            .openapi({ description: 'The action.', required: ['action'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: '' },
    204: { description: '**HTTP Status Code:** `204`<br>\nStatus updated.', content: {} },
    400: {
      description:
        "**HTTP Status Code:** `400` **Bad Request**<br><br>\n**Error Code:** `200`<br>\nZoom Room and Admin users' status can not be activated or deactivated.<br><br>\n**Error Code:** `3412`<br>Your request to activate the user was not approved at this time because your account has reached the permitted maximum number of $maxAllowedNumber basic users. Please remove existing basic user(s) from your Users list or the Pending Users list before attempting to activate this user.<br>\n**Error Code:** `2033`<br>Your request to activate the basic user was not approved because you have already reached the maximum basic user limit allowed in your account. For additional help regarding this issue, contact the Zoom Customer Support team.\n",
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br><br>\n**Error Code:** `1001`<br>\nUser does not exist: $userId.\n',
    },
  },
  security: [{ OAuth: [] }],
})

export const getUsersUserIdTokenRoute = createRoute({
  method: 'get',
  path: '/users/{userId}/token',
  tags: ['Users'],
  summary: 'Get a user token',
  description:
    "Retrieve a user's token.<br><br> This token is used for starting meetings with the Client SDK.<br>\n**Scopes:** `user:read:admin` `user:read`<br>\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\nIf a user signed into Zoom using Google or Facebook, a null value will be returned for the token. To get the token with this API, ask the user to sign into Zoom using their email and password instead.",
  operationId: 'userToken',
  request: {
    params: z.object({
      userId: z
        .string()
        .openapi({
          param: {
            description:
              'The user ID or email address of the user. For user-level apps, pass `me` as the value for userId.',
            in: 'path',
            name: 'userId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      type: z
        .enum(['token', 'zak'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'User token types:<br>`token` - Used for starting meetings with the client SDK. This token expires in 14 days and a new token will be returned after the expiry.<br>`zak` - Used for generating the start meeting URL. The token expiration time is two hours. For API users, the expiration time is 90 days.',
            in: 'query',
            name: 'type',
            schema: { enum: ['token', 'zak'], type: 'string' },
            'x-enum-descriptions': [
              'Used for starting meeting with client SDK.',
              'Used for generating the start meeting url. The expiration time is two hours. For API users, the expiration time is 90 days.',
            ],
            required: false,
          },
        }),
      ttl: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Use this field in conjunction with the `type` field where the value of `type` field is `zak`. The value of this field denotes the expiry time of the `zak` token in seconds. For example, if you would like the zak token to be expired after one hour of the token generation, the value of this field should be `3600`.',
            in: 'query',
            name: 'ttl',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '**HTTP Status Code:** `200`<br>\nToken returned.',
      content: {
        'application/json': {
          schema: z
            .object({ token: z.string().exactOptional().openapi({ description: 'User token.' }) })
            .openapi({ required: [] }),
          examples: { response: { value: { token: 'string' } } },
        },
        'application/xml': {
          schema: z
            .object({ token: z.string().exactOptional().openapi({ description: 'User token.' }) })
            .openapi({ required: [] }),
        },
      },
    },
    404: {
      description:
        '**HTTP Status Code:** `404` **Not Found**<br><br>\n**Error Code:** `1001`<br>\nUser does not exist: $userId.\n',
    },
  },
  security: [{ OAuth: [] }],
})

