export const deleteUsersUserIdTspTspIdRoute = createRoute({
  method: 'delete',
  path: '/users/{userId}/tsp/{tspId}',
  tags: ['TSP'],
  summary: "Delete a user's TSP account",
  description:
    "Delete a user's TSP account.<br><br>\n**Scopes:** `tsp:write:admin` `tsp:write`<br>\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`\n",
  operationId: 'userTSPDelete',
  request: {
    params: z.object({
      userId: z
        .string()
        .openapi({
          param: {
            description:
              'The user ID or email address of the user. For user-level apps, pass `me` as the value for userId.',
            in: 'path',
            name: 'userId',
            required: true,
            schema: { type: 'string' },
          },
        }),
      tspId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.union([z.literal(1), z.literal(2)]),
        )
        .openapi({
          param: {
            description: 'TSP account ID.',
            in: 'path',
            name: 'tspId',
            required: true,
            schema: { enum: [1, 2], type: 'string' },
          },
        }),
    }),
  },
  responses: {
    204: { description: '**Status Code:** `204` **No Content**<br>\nTSP account deleted.' },
    400: {
      description:
        '**HTTP Status Code:** `400`<br>\nBad request.<br>\n**Error Code:**`2024`<br>\nAccount not enable TSP.<br>\n**Error Code:** `300`<br>\nThe TSP id provided does not exist.<br>\n**Error Code:** `300`<br>\nTSP Config does not exist.<br>\n**Error Code:** `300`<br>\nAt least one tsp config must be available.',
    },
    404: {
      description:
        '**HTTP Status Code:** `404`<br>\nNot Found.<br>\n**Error Code:** `1001`<br>\nUser does not exist: $userId.<br>\n**Error Code:**`1120`<br>\nA valid invitation to join the Zoom account was not found for this user.<br>\nThis error is thrown if you added a user in your account but the user did not accept the invitation on time and the invitation expired - thus making the userId invalid.',
    },
  },
})

