export const deleteWebinarsWebinarIdPollsPollIdRoute = createRoute({
  method: 'delete',
  path: '/webinars/{webinarId}/polls/{pollId}',
  tags: ['Webinars'],
  summary: 'Delete a webinar poll',
  description:
    "Delete a webinar's [poll](https://support.zoom.us/hc/en-us/articles/203749865-Polling-for-Webinars).<br><br>\n**Scopes:** `webinar:write:admin` `webinar:write`<br>\n \n **[Rate Limit Label](https://marketplace.zoom.us/docs/api-reference/rate-limits#rate-limits):** `Light`<br>\n\n",
  operationId: 'webinarPollDelete',
  request: {
    params: z.object({
      webinarId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The webinar ID in "**long**" format(represented as int64 data type in JSON). ',
            in: 'path',
            name: 'webinarId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      pollId: z
        .string()
        .openapi({
          param: {
            description: 'The poll ID',
            in: 'path',
            name: 'pollId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    204: { description: '**HTTP Status Code:** `204`<br>\nWebinar Poll deleted' },
    404: {
      description:
        '**HTTP Status Code:** `404`<br>\nWebinar poll not found.<br>\n**Error Code:** `3001`<br>\nWebinar {webinarId} not found or has expired.<br>',
    },
  },
  security: [{ OAuth: [] }],
})

